/** (Importers live in build.ts and are not loaded here.) Verified part catalog (plan §6 M2). Data lives in data/catalog.json (generated by `npm run catalog:import`, plus approved overlays). */
import {readFileSync} from 'node:fs';
import {PartRecordSchema} from './schema.js';
import type {PartRecord} from './schema.js';
import type {Merged} from './merge.js';
/** Shape of data/catalog.json. */
export interface CatalogFile extends Merged{catalogVersion:string;schemaVersion:number}

export * from './schema.js';
export {searchParts,floorConfidence} from './search.js';
export type {SearchQuery,SearchHit} from './search.js';
export {mergeFragments,applyOverlay} from './merge.js';
export type {Merged,OverlayEntry} from './merge.js';

export const CATALOG_DATA_URL=new URL('./data/catalog.json',import.meta.url);
let cache:CatalogFile|undefined;
/** Load and validate the committed catalog (cached). */
export function loadCatalog():CatalogFile{
 if(cache)return cache;
 const raw=JSON.parse(readFileSync(CATALOG_DATA_URL,'utf8')) as CatalogFile;
 cache={...raw,parts:raw.parts.map(p=>PartRecordSchema.parse(p))};
 return cache;
}
export function getPart(id:string,parts:readonly PartRecord[]=loadCatalog().parts):PartRecord|undefined{return parts.find(p=>p.identity.id===id);}
